ALTER TYPE public.psa_block_type ADD VALUE IF NOT EXISTS 'letter';
CREATE TABLE public.psa_letter_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), templates jsonb NOT NULL DEFAULT '{}'::jsonb, signatory_name text NOT NULL DEFAULT 'Luis Pedra Silva', signature_data text, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid DEFAULT auth.uid(), CONSTRAINT signature_image_only CHECK(signature_data IS NULL OR (length(signature_data)<1500000 AND signature_data ~ '^data:image/(png|jpeg);base64,[A-Za-z0-9+/=]+$')));
GRANT SELECT,INSERT,UPDATE ON public.psa_letter_settings TO authenticated;
GRANT ALL ON public.psa_letter_settings TO service_role;
REVOKE ALL ON public.psa_letter_settings FROM anon;
REVOKE TRUNCATE ON public.psa_letter_settings FROM anon,authenticated;
ALTER TABLE public.psa_letter_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY letter_settings_read ON public.psa_letter_settings FOR SELECT TO authenticated USING(public.is_psa_staff() AND (public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'crm.pipeline')));
CREATE POLICY letter_settings_insert ON public.psa_letter_settings FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY letter_settings_update ON public.psa_letter_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.psa_letter_settings_stamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.revision:=CASE WHEN TG_OP='INSERT' THEN 1 ELSE OLD.revision+1 END; NEW.updated_at:=now();NEW.updated_by:=auth.uid();RETURN NEW;END $$;
CREATE TRIGGER psa_letter_settings_stamp BEFORE INSERT OR UPDATE ON public.psa_letter_settings FOR EACH ROW EXECUTE FUNCTION public.psa_letter_settings_stamp();
CREATE OR REPLACE FUNCTION public.psa_apply_master_on_creation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.psa_master_page_defaults%ROWTYPE; l public.psa_letter_settings%ROWTYPE; BEGIN IF NOT(coalesce(NEW.style_settings,'{}'::jsonb)?'masterPage') THEN SELECT * INTO d FROM public.psa_master_page_defaults WHERE id; IF FOUND THEN NEW.style_settings:=coalesce(NEW.style_settings,'{}'::jsonb)||jsonb_build_object('masterPage',d.template,'masterRevision',d.revision,'masterCustomized',false); END IF; END IF; IF NOT(coalesce(NEW.style_settings,'{}'::jsonb)?'letterSettings') THEN SELECT * INTO l FROM public.psa_letter_settings WHERE id; NEW.style_settings:=coalesce(NEW.style_settings,'{}'::jsonb)||jsonb_build_object('pageTypesEnabled',true,'letterSettings',jsonb_build_object('templates',coalesce(l.templates,'{}'::jsonb),'signatoryName',coalesce(l.signatory_name,'Luis Pedra Silva'),'signatureData',l.signature_data)); END IF; RETURN NEW; END $$;